1	// End-to-end regression coverage for the homepage draft-save race:
2	// after clicking save, the user keeps typing while waiting for the response.
3	// Those later keystrokes must neither be lost when the save succeeds nor be
4	// falsely reported as saved. Scenarios exercise the real form, status text,
5	// draft list, a second save and reopening the draft — never just the API.
6	//
7	// Run: node test/run.mjs   (CHROME_BIN can override the browser executable)
8	import assert from 'node:assert/strict';
9	import { setTimeout as sleep } from 'node:timers/promises';
10	import { Browser } from './cdp.mjs';
11	import { TestServer } from './server.mjs';
12	import * as ui from './ui.mjs';
13	
14	const tests = [];
15	function test(name, fn) { tests.push({ name, fn }); }
16	
17	// Poll the server directly until it has persisted at least `count` articles.
18	// Used with the save gate's capture mode, where the save request really
19	// reaches the server and only its response is parked in the page.
20	async function waitForServerArticles(server, count) {
21	  const deadline = Date.now() + 5000;
22	  for (;;) {
23	    const articles = await server.listArticles();
24	    if (articles.length >= count) return articles;
25	    if (Date.now() > deadline) throw new Error(`server did not persist ${count} articles in time`);
26	    await sleep(25);
27	  }
28	}
29	
30	async function seed(server, fields) {
31	  const res = await server.api('/api/articles', {
32	    method: 'POST',
33	    body: JSON.stringify({ summary: '', ...fields }),
34	  });
35	  assert.equal(res.status, 201, `seed failed: ${res.status}`);
36	  return (await res.json()).article;
37	}
38	
39	// Seeds happen out-of-band (as if saved in another tab), so the page must
40	// reload its list before the user can click the new draft's 编辑 button.
41	async function seedAndReload(server, page, fields) {
42	  const article = await seed(server, fields);
43	  await ui.reload(page);
44	  return article;
45	}
46	
47	async function freshContext(browser) {
48	  const server = await TestServer.start();
49	  const page = await ui.open(browser, server.url);
50	  return { server, page };
51	}
52	
53	async function closeContext({ server, page }, browser) {
54	  ui.assertNoPageErrors(page);
55	  await browser.closePage(page);
56	  await server.stop();
57	}
58	
59	// Body text exercising plain-text fidelity: Chinese, other scripts, newlines,
60	// blank lines and HTML-like markup that must never be parsed or executed.
61	const RICH_BODY = '多行正文第一段\n\n中间空行\n\n中文 English café 日本語 العربية 한국어\n\n'
62	  + '<script>alert(1)</script>\n<img src=x onerror=alert(2)><b>不应加粗</b>\n<div>末段</div>';
63	
64	async function getArticle(server, id) {
65	  const res = await server.api(`/api/articles/${id}`);
66	  assert.equal(res.status, 200);
67	  return (await res.json()).article;
68	}
69	
70	// An out-of-band update, exactly as if another tab saved the draft.
71	async function updateOut(server, id, fields, version) {
72	  const res = await server.api(`/api/articles/${id}`, {
73	    method: 'PUT',
74	    body: JSON.stringify({ summary: '', ...fields, version }),
75	  });
76	  const data = await res.json().catch(() => ({}));
77	  return { status: res.status, article: data.article, error: data.error };
78	}
79	
80	// Puts the page into the post-409 state: it opened v1, holds `mine` in the
81	// form, and another tab has since saved v2, so the page's save is rejected
82	// with the side-by-side conflict comparison.
83	async function stageStaleConflict(server, page, v1, mine, v2) {
84	  const article = await seedAndReload(server, page, v1);
85	  await ui.clickEdit(page, v1.title);
86	  await ui.waitLoadedDraft(page);
87	  await ui.fill(page, mine);
88	  const up = await updateOut(server, article.id, v2, 1);
89	  assert.equal(up.status, 200, `other-tab update should succeed: ${up.status} ${up.error || ''}`);
90	  await ui.clickSave(page);
91	  await ui.waitForStatus(page, '409', 'err');
92	  await ui.waitConflictShown(page);
93	  return { article, saved: up.article };
94	}
95	
96	// The comparison columns render with textContent: markup-like text must appear
97	// verbatim and must not create elements or run handlers (no dialog may fire).
98	async function assertConflictPlainText(page) {
99	  const injected = await page.eval(
100	    `document.querySelectorAll('#conflict-box .ver script,#conflict-box .ver img,#conflict-box .ver b').length`);
101	  assert.equal(injected, 0);
102	  assert.equal(page.dialogs.length, 0);
103	}
104	
105	// ---------------------------------------------------------------------------
106	// 1. Editing an existing draft: save, keep typing during the wait, save again.
107	// ---------------------------------------------------------------------------
108	test('编辑态保存等待期间继续输入：内容保留、只提示未保存字段、再次保存生效、重开一致', async (browser) => {
109	  const ctx = await freshContext(browser);
110	  const { server, page } = ctx;
111	  try {
112	    const a = await seedAndReload(server, page, {
113	      title: '原标题',
114	      summary: '原摘要',
115	      body: '原正文第一段\n\n原正文第二段',
116	    });
117	
118	    // 用户实际操作：打开已有草稿（正文以单篇接口返回为准）。
119	    await ui.clickEdit(page, '原标题');
120	    await ui.waitLoadedDraft(page);
121	    let s = await ui.state(page);
122	    assert.equal(s.saveBtnText, '保存修改');
123	    assert.deepEqual(s.form, { title: '原标题', summary: '原摘要', body: '原正文第一段\n\n原正文第二段' });
124	    assert.equal(s.bannerId, a.id);
125	
126	    // 提交标题、摘要、正文。
127	    await ui.fill(page, {
128	      title: '  修改后的标题  ',
129	      summary: '实际提交的摘要 <b>x</b>',
130	      body: '实际提交的正文第一段\n\n实际提交的正文第二段',
131	    });
132	    await ui.gateOn(page);
133	    await ui.clickSave(page);
134	    await ui.waitSavingPending(page, 1);
135	
136	    // 等待响应期间：标题不动，摘要补写、正文重写（含换行、空行、多语言、类 HTML 文本）。
137	    await ui.fill(page, {
138	      summary: '等待期间补写的摘要',
139	      body: '等待期间的正文\n\n空行保留\n\n中文 English café 日本語 العربية\n\n<html>原样文本</html>',
140	    });
141	    // 保存进行中重复点击不会产生第二次提交。
142	    await ui.clickSave(page);
143	    s = await ui.state(page);
144	    assert.equal(s.saveDisabled, true);
145	    assert.deepEqual(await page.eval(`__qtest.gateState()`), { enabled: true, hits: 1, pending: 1 });
146	    // 成功返回前列表仍是旧内容：不能提前显示尚未保存成功的东西。
147	    assert.equal(s.cards[0].title, '原标题');
148	    assert.equal(s.cards[0].summary, '原摘要');
149	
150	    await ui.releaseSaves(page);
151	    await ui.gateOff(page);
152	    await ui.waitForStatus(page, '尚未保存', 'warn');
153	    s = await ui.state(page);
154	
155	    // 明确指出哪些字段还有未保存修改（标题不在其列）。
156	    assert.match(s.statusText, /但摘要、正文在保存期间又被修改/);
157	    assert.ok(!s.statusText.includes('标题在保存期间'));
158	    // 表单保留等待期间输入的当前值，一个字符都不动。
159	    assert.equal(s.form.title, '修改后的标题'); // 本次提交的标题按规则去首尾空白
160	    assert.equal(s.form.summary, '等待期间补写的摘要');
161	    assert.equal(s.form.body,
162	      '等待期间的正文\n\n空行保留\n\n中文 English café 日本語 العربية\n\n<html>原样文本</html>');
163	    // 仍编辑同一篇草稿。
164	    assert.equal(s.formEditing, true);
165	    assert.equal(s.bannerHidden, false);
166	    assert.equal(s.bannerId, a.id);
167	    assert.equal(s.bannerTitle, '修改后的标题');
168	    assert.equal(s.saveBtnText, '保存修改');
169	    assert.equal(s.saveDisabled, false);
170	    // 列表反映的是本次实际提交并保存的标题与摘要，不是等待期间的新输入。
171	    assert.equal(s.listCount, 1);
172	    assert.equal(s.cards[0].title, '修改后的标题');
173	    assert.equal(s.cards[0].summary, '实际提交的摘要 <b>x</b>');
174	    assert.equal(s.cards[0].editing, true);
175	    // 类 HTML 的摘要按文本渲染，不执行任何标记。
176	    assert.equal(await page.eval(`document.querySelectorAll('#article-list .summary').length`), 1);
177	    assert.equal(await page.eval(`document.querySelector('#article-list .summary b')`), null);
178	
179	    // 服务端状态：同一篇草稿，版本推进，标识/创建时间/状态不变，存的是实际提交内容。
180	    let saved = await (await server.api(`/api/articles/${a.id}`)).json();
181	    assert.equal(saved.article.id, a.id);
182	    assert.equal(saved.article.createdAt, a.createdAt);
183	    assert.equal(saved.article.status, 'draft');
184	    assert.equal(saved.article.version, 2);
185	    assert.equal(saved.article.title, '修改后的标题');
186	    assert.equal(saved.article.summary, '实际提交的摘要 <b>x</b>');
187	    assert.equal(saved.article.body, '实际提交的正文第一段\n\n实际提交的正文第二段');
188	
189	    // 再次点击“保存修改”：刚才保留的内容才成为已保存内容，且不能误报冲突。
190	    await ui.clickSave(page);
191	    await ui.waitForStatus(page, '修改已保存', 'ok');
192	    s = await ui.state(page);
193	    assert.equal(s.conflictHidden, true);
194	    assert.equal(s.cards[0].summary, '等待期间补写的摘要');
195	    saved = await (await server.api(`/api/articles/${a.id}`)).json();
196	    assert.equal(saved.article.version, 3);
197	    assert.equal(saved.article.id, a.id);
198	    assert.equal(saved.article.createdAt, a.createdAt);
199	    assert.equal(saved.article.body,
200	      '等待期间的正文\n\n空行保留\n\n中文 English café 日本語 العربية\n\n<html>原样文本</html>');
201	    assert.equal(s.listCount, 1);
202	
203	    // 再次打开草稿：完整正文（含空行与类 HTML 文本）以单篇接口返回为准被载入。
