// Scratch verification of existing server size-limit semantics via raw sockets.
import net from 'node:net';
import { TestServer } from './test/server.mjs';

const MAX = 5 * 1024 * 1024;
const server = await TestServer.start();
const port = new URL(server.url).port;

function open() {
  return new Promise((resolve, reject) => {
    const sock = net.connect(port, '127.0.0.1');
    sock.once('connect', () => resolve(sock));
    sock.once('error', reject);
  });
}

function sendRaw(requestChunks) {
  return new Promise(async (resolve, reject) => {
    const sock = await open();
    const chunks = [];
    sock.on('data', (c) => chunks.push(c));
    sock.on('end', () => resolve(Buffer.concat(chunks)));
    sock.on('error', reject);
    let i = 0;
    const writeNext = () => {
      if (i >= requestChunks.length) { sock.end(); return; }
      sock.write(requestChunks[i++], writeNext);
    };
    writeNext();
  });
}

function requestLine(method, target, headers) {
  return Buffer.from(`${method} ${target} HTTP/1.1\r\nHost: 127.0.0.1\r\n${headers}\r\n`, 'ascii');
}

function parseHead(raw) {
  const idx = raw.indexOf('\r\n\r\n');
  const head = raw.slice(0, idx).toString('latin1');
  const [statusLine, ...lines] = head.split('\r\n');
  const headers = Object.fromEntries(lines.map((l) => {
    const i = l.indexOf(':');
    return [l.slice(0, i).toLowerCase(), l.slice(i + 1).trim()];
  }));
  return { statusLine, headers, body: raw.slice(idx + 4) };
}

function chunkFrame(payload) {
  // payload: Buffer[] -> single chunked-encoding buffer
  const total = payload.reduce((n, b) => n + b.length, 0);
  return Buffer.concat([
    Buffer.from(total.toString(16) + '\r\n', 'ascii'),
    ...payload,
    Buffer.from('\r\n0\r\n\r\n'),
  ]);
}

// Build a JSON object request body of EXACTLY `target` bytes:
// {"title":"t","summary":"s","body":"<pad>"}
// Overhead for create with a 1-char title/summary:
// {"title":"t","summary":"s","body":""} => count
function createBodyOfSize(target) {
  const fixed = '{"title":"t","summary":"s","body":""}';
  const overhead = Buffer.byteLength(fixed) - 2; // room is between the body quotes
  const pad = 'x'.repeat(target - overhead);
  return Buffer.from(`{"title":"t","summary":"s","body":"${pad}"}`, 'utf8');
}

function updateBodyOfSize(target) {
  const fixed = '{"title":"t","summary":"s","body":"","version":1}';
  const overhead = Buffer.byteLength(fixed) - 2;
  const pad = 'x'.repeat(target - overhead);
  return Buffer.from(`{"title":"t","summary":"s","body":"${pad}","version":1}`, 'utf8');
}

