const results = [];
async function probe(label, method, target, body, mode, opts = {}) {
  let raw;
  if (mode === 'length') {
    const head = requestLine(method, target,
      `content-type: application/json\r\ncontent-length: ${body.length}\r\nconnection: close\r\n`);
