    const head = requestLine(method, target,
      `content-type: application/json\r\ntransfer-encoding: chunked\r\nconnection: close\r\n`);
    if (opts.singleFrame) {
      raw = await sendRaw([head, chunkFrame(body), Buffer.from('0\r\n\r\n')]);
    } else {
      // First frame carries just 1024 bytes (well within limit); the second
      // frame carries the remainder and pushes cumulative bytes over.
      const cut = 1024;
      raw = await sendRaw([
        head,
        chunkFrame(body.slice(0, cut)),
        chunkFrame(body.slice(cut)),
        Buffer.from('0\r\n\r\n'),
      ]);
    }
  }
  const parsed = parseHead(raw);
  const statusCode = Number(parsed.statusLine.split(' ')[1]);
  let json = null;
  try { json = JSON.parse(parsed.body.toString('utf8')); } catch { /* not json */ }
  const bodyComplete = parsed.headers['content-length']
    ? parsed.body.length === Number(parsed.headers['content-length'])
    : null;
  results.push({
    label, mode, bytes: body.length, statusCode,
    err: json && json.error ? String(json.error).slice(0, 70) : null,
    bodyComplete, gotBytes: parsed.body.length,
  });
}

