  sizedBody(CREATE_PREFIX, CREATE_SUFFIX, MAX, 'x'), 'length');
await probe('POST MAX+1', 'POST', '/api/articles',
  sizedBody(CREATE_PREFIX, CREATE_SUFFIX, MAX + 1, 'x'), 'length');
await probe('POST MAX+1 chunked', 'POST', '/api/articles',
  sizedBody(CREATE_PREFIX, CREATE_SUFFIX, MAX + 1, 'x'), 'chunked');
await probe('PUT exact MAX', 'PUT', `/api/articles/${seed.id}`,
  sizedBody(UPDATE_PREFIX, UPDATE_SUFFIX, MAX, 'x'), 'length');
await probe('PUT MAX+1', 'PUT', `/api/articles/${seed.id}`,
  sizedBody(UPDATE_PREFIX, UPDATE_SUFFIX, MAX + 1, 'x'), 'length');
await probe('PUT MAX+1 chunked', 'PUT', `/api/articles/${seed.id}`,
  sizedBody(UPDATE_PREFIX, UPDATE_SUFFIX, MAX + 1, 'x'), 'chunked');

