const cnPre = Buffer.from(CREATE_PREFIX, 'utf8');
const cnSuf = Buffer.from(CREATE_SUFFIX, 'utf8');
for (const want of [MAX, MAX + 1]) {
  const padBytes = want - cnPre.length - cnSuf.length;
  const n = Math.floor(padBytes / 3);
  const rem = padBytes - n * 3;
  // pad = n CJK chars + rem ASCII chars so total aligns exactly
  const pad = Buffer.concat([
    Buffer.from('中'.repeat(n), 'utf8'),
    Buffer.from('a'.repeat(rem), 'utf8'),
  ]);
  const body = Buffer.concat([cnPre, pad, cnSuf]);
  await probe(`POST multibyte exact ${want === MAX ? 'MAX' : 'MAX+1'} (chars=${n})`, 'POST',
    '/api/articles', body, 'length');
  if (want === MAX + 1) {
    await probe('POST multibyte MAX+1 chunked', 'POST', '/api/articles', body, 'chunked');
  }
}

