  const pad = Buffer.concat([Buffer.from('中'.repeat(n), 'utf8'), Buffer.from('a'.repeat(rem), 'utf8')]);
  const body = Buffer.concat([pre, pad, suf]);
  await probe('POST body-small summary-over (body chars=5)', 'POST', '/api/articles', body, 'length');
}

