// Keep-alive probe: oversized chunked body on a reusable connection must still
// deliver a fully framed 400, and the same socket must serve a follow-up request.
import net from 'node:net';
import { TestServer } from './test/server.mjs';

const MAX = 5 * 1024 * 1024;
const server = await TestServer.start();
const port = new URL(server.url).port;

const sock = net.connect(port, '127.0.0.1');
await new Promise((r) => sock.once('connect', r));

const buf = Buffer.concat([
  Buffer.from('POST /api/articles HTTP/1.1\r\nHost: x\r\nContent-Type: application/json\r\nTransfer-Encoding: chunked\r\n\r\n', 'ascii'),
  Buffer.from('400\r\n' + 'x'.repeat(1024) + '\r\n', 'ascii'),
]);
const big = 'y'.repeat(MAX); // second frame alone is ~5MiB, cumulative > MAX
const rest = Buffer.concat([
  Buffer.from(big.length.toString(16) + '\r\n', 'ascii'),
  Buffer.from(big, 'ascii'),
  Buffer.from('\r\n0\r\n\r\n'),
]);
sock.write(buf);
await new Promise((r) => setTimeout(r, 200));
sock.write(rest);

// Read the first response (should be 400 with content-length, connection alive)
let received = Buffer.alloc(0);
const first = await new Promise((resolve, reject) => {
  const onData = (c) => {
    received = Buffer.concat([received, c]);
    const idx = received.indexOf('\r\n\r\n');
    if (idx >= 0) {
      const head = received.slice(0, idx).toString('latin1');
      const m = /content-length:\s*(\d+)/i.exec(head);
      if (m && received.length - idx - 4 >= Number(m[1])) {
        sock.off('data', onData);
        resolve({ head, body: received.slice(idx + 4, idx + 4 + Number(m[1])), leftover: received.slice(idx + 4 + Number(m[1])) });
      }
    }
  };
  sock.on('data', onData);
  setTimeout(() => reject(new Error('no complete 400 on keep-alive socket; got ' + received.length + ' bytes')), 10000);
});
console.log(first.head.split('\r\n')[0]);
console.log('connection header:', /connection:\s*(\S+)/i.exec(first.head)?.[1]);
console.log('body:', first.body.toString());
console.log('leftover bytes before next request:', first.leftover.length);

// Follow-up request on the same socket.
sock.write(Buffer.from('GET /health HTTP/1.1\r\nHost: x\r\n\r\n', 'ascii'));
let got = Buffer.alloc(0);
const second = await new Promise((resolve, reject) => {
  const onData = (c) => {
    got = Buffer.concat([got, c]);
    if (got.includes('\r\n\r\n') && got.toString().includes('"status":"ok"')) {
      sock.off('data', onData);
      resolve(got.toString());
    }
  };
  sock.on('data', onData);
  setTimeout(() => reject(new Error('follow-up failed')), 10000);
});
console.log('follow-up status:', second.split('\r\n')[0]);
sock.end();
await server.stop();

